namespace ghidra.app.plugin.core.debug.gui.internal;






using docking.widgets.tree;
using ghidra.framework.plugintool;
using ghidra.trace.model;
using ghidra.util.database.spatial;

public class RStarTreeProvider : ComponentProviderAdapter {
	private RStarDiagnosticsPlugin plugin;

	interface HasShape {
		TraceAddressSnapRange getShape();
	}

	class RootRStarNode : GTreeLazyNode, HasShape {
		/* @Override */
		public TraceAddressSnapRange getShape() {
			if (plugin == null || plugin.space == null) {
				return null;
			}
			return plugin.space.getRootBounds();
		}

		/* @Override */
		public string getName() {
			TraceAddressSnapRange root = getShape();
			if (root == null) {
				return "No Shape";
			}
			return root.toString();
		}

		/* @Override */
		public Icon getIcon(bool expanded) {
			return null;
		}

		/* @Override */
		public string getToolTip() {
			return null;
		}

		/* @Override */
		public bool isLeaf() {
			return false;
		}

		/* @Override */
		protected List<GTreeNode> generateChildren() {
			if (!(getShape() is DBTreeNodeRecord<object> rec)) {
				return List.of();
			}
			return plugin.space.getChildrenOf(rec).stream().map(n => nodeFor(n)).toList();
		}
	}

	class NodeRStarNode : GTreeLazyNode, HasShape {
		DBTreeNodeRecord<object> rec;

		public NodeRStarNode(DBTreeNodeRecord<object> rec) {
			this.rec = rec;
		}

		/* @Override */
		public TraceAddressSnapRange getShape() {
			return (TraceAddressSnapRange) rec.getShape();
		}

		/* @Override */
		public string getName() {
			return rec.toString();
		}

		/* @Override */
		public Icon getIcon(bool expanded) {
			return null;
		}

		/* @Override */
		public string getToolTip() {
			return null;
		}

		/* @Override */
		public bool isLeaf() {
			return false;
		}

		/* @Override */
		protected List<GTreeNode> generateChildren() {
			return plugin.space.getChildrenOf(rec).stream().map(n => nodeFor(n)).toList();
		}
	}

	class DataRStarNode : GTreeNode, HasShape {
		DBTreeDataRecord<object,object,object> rec;

		public DataRStarNode(DBTreeDataRecord<object,object,object> rec) {
			this.rec = rec;
		}

		/* @Override */
		public TraceAddressSnapRange getShape() {
			return (TraceAddressSnapRange) rec.getShape();
		}

		/* @Override */
		public string getName() {
			return rec.toString();
		}

		/* @Override */
		public Icon getIcon(bool expanded) {
			return null;
		}

		/* @Override */
		public string getToolTip() {
			return null;
		}

		/* @Override */
		public bool isLeaf() {
			return true;
		}
	}

	Map<DBTreeRecord<object,object>, GTreeNode> nodes = new();

	private GTreeNode nodeFor(DBTreeRecord<object,object> rec) {
		if (rec == plugin.space.getRootBounds()) {
			return root;
		}
		return nodes.computeIfAbsent(rec, r => switch (rec) {
			case DBTreeNodeRecord<object> n: return new NodeRStarNode(n);
			case DBTreeDataRecord<object,object,object> d: return new DataRStarNode(d);
			default: throw new AssertionError();
		});
	}

	RootRStarNode root = new RootRStarNode();
	GTree tree = new GTree(root);
	JPanel panel = new JPanel(new BorderLayout());

	public RStarTreeProvider(RStarDiagnosticsPlugin plugin) : base(plugin.getTool(), "R*-Tree Diagnostic Tree", plugin.getName())
    {
		this.plugin = plugin;
		this.panel.add(tree);

		tree.addGTreeSelectionListener(e => {
			plugin.plotProvider.component.repaint();
		});
	}

	/* @Override */
	public JComponent getComponent() {
		return panel;
	}

	public void select(TraceAddressSnapRange shape) {
		if (!(shape is DBTreeRecord<object,object> rec)) {
			return;
		}
		tree.getSelectionModel().setSelectionPath(nodeFor(rec).getTreePath());
	}

	void refresh() {
		root.unloadChildren();
		nodes.clear();
	}
}
